/*Table structure for table `area_custom_flag` */

DROP TABLE IF EXISTS `area_custom_flag`;

CREATE TABLE `area_custom_flag` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `flag` tinyint unsigned NOT NULL,
  `mapId` tinyint unsigned NOT NULL,
  `x` float NOT NULL,
  `y` float NOT NULL,
  `z` float NOT NULL,
  `radius` int unsigned NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Data for the table `area_custom_flag` */

/*Table structure for table `boss_history` */

DROP TABLE IF EXISTS `boss_history`;

CREATE TABLE `boss_history` (
  `Guid` bigint NOT NULL AUTO_INCREMENT,
  `GuildId` int NOT NULL,
  `CreatureEntry` int NOT NULL,
  `CreatureName` varchar(255) NOT NULL,
  `KillerCount` tinyint unsigned NOT NULL DEFAULT '0',
  `KillTime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `KillData` longtext NOT NULL,
  `MapRaid` tinyint unsigned NOT NULL DEFAULT '0',
  `MapId` smallint unsigned NOT NULL DEFAULT '0',
  `MapName` varchar(255) NOT NULL,
  `MapSpawnMode` tinyint unsigned NOT NULL DEFAULT '0',
  `MapMaxPlayers` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`Guid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `boss_history` */

