/*Table structure for table `updates_include` */

DROP TABLE IF EXISTS `updates_include`;

CREATE TABLE `updates_include` (
  `path` varchar(200) NOT NULL COMMENT 'directory to include. $ means relative to the source directory.',
  `state` enum('RELEASED','ARCHIVED') NOT NULL DEFAULT 'RELEASED' COMMENT 'defines if the directory contains released or archived updates.',
  PRIMARY KEY (`path`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COMMENT='List of directories where we want to include sql updates.';

/*Data for the table `updates_include` */

insert  into `updates_include`(`path`,`state`) values 
('$/sql/updates/zyn','RELEASED'),
('$/sql/custom/zyn','RELEASED'),
('$/sql/old/3.3.5a/zyn','ARCHIVED');

/*Table structure for table `world_autolearn` */

DROP TABLE IF EXISTS `world_autolearn`;

CREATE TABLE `world_autolearn` (
  `SpellId` mediumint unsigned NOT NULL DEFAULT '0',
  `SpellMask` tinyint unsigned NOT NULL DEFAULT '0',
  `RequiredClassMask` mediumint unsigned NOT NULL DEFAULT '0',
  `RequiredRaceMask` mediumint unsigned NOT NULL DEFAULT '0',
  `RequiredLevel` tinyint unsigned NOT NULL DEFAULT '0',
  `RequiredSpellId` mediumint unsigned NOT NULL DEFAULT '0',
  `RequiredSkillId` smallint unsigned NOT NULL DEFAULT '0',
  `RequiredSkillValue` smallint unsigned NOT NULL DEFAULT '0',
  `Comment` varchar(255) NOT NULL,
  PRIMARY KEY (`SpellId`,`RequiredLevel`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

