/*Table structure for table `world_custom_reward_pvp` */

DROP TABLE IF EXISTS `world_custom_reward_pvp`;

CREATE TABLE `world_custom_reward_pvp` (
  `id` mediumint unsigned NOT NULL DEFAULT '0',
  `req_type_is_battleground` mediumint unsigned NOT NULL DEFAULT '0',
  `req_type_is_arena` mediumint unsigned NOT NULL DEFAULT '0',
  `req_zone_id` mediumint unsigned NOT NULL DEFAULT '0',
  `req_map_id` mediumint unsigned NOT NULL DEFAULT '0',
  `req_target_race_mask` mediumint unsigned NOT NULL DEFAULT '0',
  `req_target_class_mask` mediumint unsigned NOT NULL DEFAULT '0',
  `req_self_race_mask` mediumint unsigned NOT NULL DEFAULT '0',
  `req_self_class_mask` mediumint unsigned NOT NULL DEFAULT '0',
  `req_target_guid` mediumint unsigned NOT NULL DEFAULT '0',
  `req_self_guid` mediumint unsigned NOT NULL DEFAULT '0',
  `req_target_guild_id` mediumint unsigned NOT NULL DEFAULT '0',
  `req_self_guild_id` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_money_gold` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_honor` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_item_id` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_item_count` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_buff` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_group` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_rep_faction_id` mediumint unsigned NOT NULL DEFAULT '0',
  `reward_rep_value` mediumint unsigned NOT NULL DEFAULT '0',
  `disabled` mediumint unsigned NOT NULL DEFAULT '0',
  `Comment` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

/*Data for the table `world_custom_reward_pvp` */

insert  into `world_custom_reward_pvp`(`id`,`req_type_is_battleground`,`req_type_is_arena`,`req_zone_id`,`req_map_id`,`req_target_race_mask`,`req_target_class_mask`,`req_self_race_mask`,`req_self_class_mask`,`req_target_guid`,`req_self_guid`,`req_target_guild_id`,`req_self_guild_id`,`reward_money_gold`,`reward_honor`,`reward_item_id`,`reward_item_count`,`reward_buff`,`reward_group`,`reward_rep_faction_id`,`reward_rep_value`,`disabled`,`Comment`) values 
