/*Table structure for table `world_tournament_creature` */

DROP TABLE IF EXISTS `world_tournament_creature`;

CREATE TABLE `world_tournament_creature` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tournament_entry` int unsigned NOT NULL DEFAULT '0',
  `tournament_level` int unsigned NOT NULL DEFAULT '0',
  `entry` int unsigned NOT NULL DEFAULT '0',
  `count` int unsigned NOT NULL DEFAULT '0',
  `from_point_id` int unsigned NOT NULL DEFAULT '0',
  `to_point_id` int unsigned NOT NULL DEFAULT '0',
  `time` int unsigned NOT NULL DEFAULT '0',
  `comment` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb3;

