/*Table structure for table `world_tournaments` */

DROP TABLE IF EXISTS `world_tournaments`;

CREATE TABLE `world_tournaments` (
  `entry` int NOT NULL,
  `level` int unsigned NOT NULL AUTO_INCREMENT,
  `time_limit` int NOT NULL DEFAULT '0',
  `say_start` int unsigned NOT NULL DEFAULT '0',
