  `req_quest_id` int unsigned NOT NULL DEFAULT '0',
  `kill_credit` int unsigned NOT NULL DEFAULT '0',
  `menu_string` int unsigned NOT NULL DEFAULT '0',
  `comment` varchar(255) NOT NULL,
  PRIMARY KEY (`entry`,`level`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;

